<?php
declare(strict_types=1);
$config=require dirname(__DIR__).'/config/app.php';require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Core/AuditLogger.php';require dirname(__DIR__).'/app/Core/RateLimiter.php';require dirname(__DIR__).'/app/Services/Authorization.php';Security::sendSecurityHeaders($config);Security::startSession($config);if(!empty($_SESSION['user_id'])&&!Security::enforceAuthenticatedSession($config)){Security::destroySession();}
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}if(!Security::verifyCsrf($_POST['_csrf']??null)){http_response_code(419);exit('Session expired.');}
try{$ip=(string)($_SERVER['REMOTE_ADDR']??'unknown');if(!RateLimiter::allow('feedback',$ip,5,3600))throw new InvalidArgumentException('Too many feedback submissions. Please wait before sending another.');if(trim((string)($_POST['website']??''))!=='')throw new InvalidArgumentException('Submission rejected.');if(($_POST['privacy_ack']??'')!=='1')throw new InvalidArgumentException('Please acknowledge the privacy notice.');$category=(string)($_POST['category']??'');$allowed=['SERVICE','WEBSITE','COMPLAINT','SUGGESTION','COMPLIMENT','OTHER'];$subject=trim((string)($_POST['subject']??''));$message=trim((string)($_POST['message']??''));$email=strtolower(trim((string)($_POST['contact_email']??'')));if(!in_array($category,$allowed,true)||$subject===''||strlen($subject)>180||$message===''||strlen($message)>4000)throw new InvalidArgumentException('Complete the category, subject, and message.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Enter a valid contact email.');$db=Database::connection();$user=null;if(!empty($_SESSION['user_id']))$user=Authorization::user($db,(int)$_SESSION['user_id']);$q=$db->prepare("INSERT INTO feedback_submissions (user_id,category,subject,message,contact_email,status) VALUES (:uid,:category,:subject,:message,:email,'OPEN')");$q->execute(['uid'=>$user['user_id']??null,'category'=>$category,'subject'=>$subject,'message'=>$message,'email'=>$email?:null]);$id=(int)$db->lastInsertId();AuditLogger::record($db,isset($user['user_id'])?(int)$user['user_id']:null,'FEEDBACK_SUBMITTED','feedback',$id,['category'=>$category]);header('Location: feedback.php?sent=1');exit;
}catch(InvalidArgumentException $e){http_response_code(422);$msg=$e->getMessage();}catch(Throwable $e){error_log('Feedback submit: '.$e->getMessage());http_response_code(503);$msg='Unable to send feedback at this time.';}
require dirname(__DIR__).'/app/Core/PublicPage.php';pageHeader('Feedback not sent');?><main id="main-content" class="section"><div class="notice warning"><?= Security::e($msg??'Submission failed.') ?></div><a class="action-secondary" href="feedback.php">Return to feedback form</a></main><?php pageFooter();
